/**
 * The growth & SEO dashboard: /_seo/ — generated by every development build,
 * left out by `node build.mjs --production`.
 *
 * It is unlisted, `noindex`, disallowed in robots.txt and linked from nowhere,
 * but it is a static page: anyone with the address can open it. The page
 * itself contains only what the public pages already show (titles,
 * descriptions, links) and public IDs. Analytics and Search Console data are
 * loaded in the viewer's browser after they sign in with Google, so only
 * someone with access to those accounts sees them (src/scripts/growth/).
 */
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const EVENT_ROWS = [
  ['seo_page_view', 'A template, guide, tool, hub or generator page is viewed', '—'],
  ['template_view', 'A template page is viewed', 'template'],
  ['guide_view', 'A guide is viewed', '—'],
  ['tool_view', 'A tool page is viewed', 'tool'],
  ['template_selected', 'A template is chosen: Customize, Start blank, Use template, or in the generator’s picker', 'template, cta'],
  ['generator_cta_clicked', 'Any link into the generator is clicked', 'cta (header, bottom, article, tool, card…), template, tool'],
  ['tool_used', 'A tool’s inputs are first changed', 'tool'],
  ['invoice_generator_opened', 'The generator loads', 'via (template, tool, guide, home, site, direct), template, from_page'],
  ['invoice_started', 'A new invoice is started: blank, example, prefill or duplicate', 'template, layout, via, start'],
  ['invoice_created', 'An invoice is first edited, or first exported with content (once per invoice)', 'template, layout, via, start'],
  ['pdf_downloaded', 'A PDF is downloaded', 'template, layout, via, start'],
  ['print_clicked', 'Print is used', 'template, layout, via, start'],
  ['payment_link_created', 'A Stripe or PayPal payment link is created for an invoice (including regenerated links)', 'provider, template, layout'],
  ['payment_link_clicked', 'A payment link is opened for the first time (reported by the sender’s generator; the payer is never tracked)', 'provider, template, layout'],
  ['invoice_payment_completed', 'Stripe or PayPal confirms the payment (reported once per link by the sender’s generator)', 'provider, template, layout'],
];

const SKELETONS = {
  template: {
    file: 'src/content/templates/<slug>.json',
    body: JSON.stringify({
      name: 'Roofer',
      layout: 'contractor',
      title: 'Free Roofer Invoice Template',
      description: '80–165 characters: what the template is for, what it includes, and that it is free to fill in and download as a PDF.',
      summary: 'One sentence for the template card.',
      intro: 'The lead paragraph under the heading.',
      explanation: ['Why this invoice is laid out the way it is, for this kind of work.'],
      fieldsTitle: 'What to put on a roofing invoice',
      fields: [{ name: 'Field', text: 'Why it belongs on the invoice, with an example.' }],
      steps: [{ title: 'Step', text: 'What to do in the generator.' }],
      faqs: [{ q: 'A question people ask?', a: 'A direct answer. Links: [text](/invoice-guides/…/).' }],
      sample: '(optional) { business, client, project, items: [[description, qty, price, group]], adjustments, payment, notes }',
      relatedTemplates: ['contractor'],
      relatedGuides: ['what-to-put-on-an-invoice'],
      relatedTools: ['invoice-tax-calculator'],
      updated: '2026-10-01',
      status: 'draft',
    }, null, 2),
  },
  guide: {
    file: 'src/content/guides/<slug>.md',
    body: `---
name: Short name for lists
title: The question, as the page heading
metaTitle: (optional) title tag, if different
description: 80–165 characters that answer the question.
summary: One or two sentences under the heading and in lists.
group: Basics
updated: 2026-10-01
howto: (optional) the ## heading whose numbered list is a set of steps
relatedTemplates: freelancer, small-business
relatedGuides: what-to-put-on-an-invoice
relatedTools: invoice-number-generator
status: draft
---
Opening paragraph that answers the question directly.

## A section

Paragraphs, - lists, 1. steps, | tables |, > notes, [links](/invoice-templates/).

[[invoice: contractor | A caption for a real rendered example]]

## Frequently asked questions

### A question?

The answer.`,
  },
  tool: {
    file: 'src/content/tools/<slug>.md  +  src/partials/tool-<slug>.html  +  src/scripts/tools/<slug>.js',
    body: '(as a guide, without group/howto; the widget markup and its script are separate files)',
  },
};

export function dashboard({ site, pages, content, cssVersion, appVersion, analytics }) {
  const rows = pages.slice().sort((a, b) => a.type.localeCompare(b.type) || a.url.localeCompare(b.url));
  const types = [...new Set(rows.map((p) => p.type))];
  const live = rows.filter((p) => p.indexable);
  const flagged = rows.filter((p) => p.issues?.length);
  const words = live.filter((p) => ['template', 'guide', 'tool'].includes(p.type));
  const avg = words.length ? Math.round(words.reduce((s, p) => s + p.words, 0) / words.length) : 0;
  const len = (s, lo, hi) => `<span class="${s.length < lo || s.length > hi ? 'dash__bad' : 'dash__ok'}">${s.length}</span>`;

  const table = rows.map((p) => `<tr data-type="${p.type}">
      <td><span class="label">${esc(p.type)}</span></td>
      <td><a class="link" href="..${esc(p.url)}">${esc(p.url)}</a>${p.redirect ? `<br><span class="muted">→ ${esc(p.redirect)}</span>` : ''}</td>
      <td>${esc(p.title || '')} ${p.title ? len(p.title, 10, 65) : ''}</td>
      <td>${esc(p.description || '')} ${p.description ? len(p.description, 80, 170) : ''}</td>
      <td>${esc(p.h1 || '')}</td>
      <td class="num">${p.words ?? ''}</td>
      <td class="num">${p.inbound ?? ''} / ${p.links ? p.links.length : ''}</td>
      <td>${esc((p.schema || []).join(', '))}</td>
      <td>${p.indexable ? 'Yes' : 'No'}</td>
      <td class="dash__canon">${esc((p.canonical || '').replace(site.url, '') || '')}</td>
      <td>${p.issues?.length ? `<span class="dash__bad">${esc(p.issues.join('; '))}</span>` : '<span class="dash__ok">—</span>'}</td>
    </tr>`).join('');

  const drafts = content.drafts.length
    ? `<ul class="feature__list">${content.drafts.map((e) => `<li><strong>${esc(e.title)}</strong> · ${esc(e.file)} · would publish at ${esc(e.url)}</li>`).join('')}</ul>`
    : '<p class="muted">No drafts. Set <code>status: draft</code> in an entry to hold it back from the site.</p>';

  // What the growth dashboard needs to name pages and know their kind.
  const names = new Map(content.published.map((e) => [e.url, e]));
  const index = pages.filter((p) => p.type !== 'redirect').map((p) => {
    const e = names.get(p.url);
    const type = p.url === '/app/' ? 'app' : p.type;
    return { path: p.url, type, slug: e ? e.slug : '', name: e ? e.name : p.url === '/' ? 'Home' : p.url === '/app/' ? 'Generator' : p.h1 || p.url };
  });
  const config = {
    measurementConfigured: Boolean(analytics.ga4),
    ga4PropertyId: analytics.ga4PropertyId,
    oauthClientId: analytics.oauthClientId,
    searchConsoleSite: analytics.searchConsoleSite,
  };
  const data = (id, v) => `<script type="application/json" id="${id}">${JSON.stringify(v).replace(/</g, '\\u003c')}</script>`;

  return `<!doctype html>
<html lang="en-US">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Growth &amp; SEO dashboard — ${esc(site.name)}</title>
  <meta name="robots" content="noindex, nofollow">
  <link rel="stylesheet" href="../assets/site.css?v=${cssVersion}">
  <style>
    .dash { padding-block: var(--s-7) var(--s-9); }
    .dash h1 { margin-bottom: var(--s-3); }
    .dash__sum { display: flex; flex-wrap: wrap; gap: var(--s-5) var(--s-7); margin: var(--s-6) 0; padding: var(--s-4) 0; border-top: var(--hair-ink); border-bottom: var(--hair); }
    .dash__sum div { display: grid; }
    .dash__sum strong { font-size: var(--fs-h3); font-weight: 400; }
    .dash__filters { display: flex; flex-wrap: wrap; gap: var(--s-2); margin: var(--s-5) 0; }
    .dash__scroll { overflow-x: auto; border-top: var(--hair-ink); }
    .dash table { border-collapse: collapse; font-size: 0.8125rem; line-height: 1.4; width: 100%; }
    .dash__audit table { min-width: 1500px; }
    .dash th, .dash td { text-align: left; vertical-align: top; padding: var(--s-2) var(--s-3) var(--s-2) 0; border-bottom: var(--hair); }
    .dash th { font-family: var(--sans); font-weight: 500; font-size: 0.6875rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ash); position: sticky; top: 0; background: var(--bone); }
    .dash td.num { font-variant-numeric: tabular-nums; white-space: nowrap; }
    .dash__canon { max-width: 16ch; word-break: break-all; }
    .dash__bad { color: var(--error); font-family: var(--sans); font-size: 0.75rem; }
    .dash__ok { color: var(--ash); font-family: var(--sans); font-size: 0.75rem; }
    .dash pre { background: var(--ivory); padding: var(--s-4); overflow-x: auto; font-size: 0.8125rem; line-height: 1.5; border-top: var(--hair-ink); }
    .dash section { margin-top: var(--s-8); }
    .dash h2 { margin-bottom: var(--s-4); }
    /* growth */
    .g-jump { display: flex; flex-wrap: wrap; gap: var(--s-2) var(--s-5); margin: var(--s-5) 0 0; font-size: var(--fs-small); }
    .g-bar { display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--s-4) var(--s-6); align-items: center; margin-top: var(--s-6); padding: var(--s-4) 0; border-top: var(--hair-ink); border-bottom: var(--hair); position: sticky; top: 0; background: var(--bone); z-index: 2; }
    .g-range { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2); }
    .g-range input { font: inherit; font-size: 0.875rem; padding: 0.3rem 0.4rem; border: 1px solid var(--rule); background: var(--ivory); }
    .g-custom { display: inline-flex; flex-wrap: wrap; gap: var(--s-2); align-items: center; }
    .g-custom[hidden] { display: none; }
    .g-conn { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2) var(--s-4); font-size: 0.875rem; }
    .g-status { color: var(--ash); }
    .g-period { margin-top: var(--s-3); color: var(--ash); font-size: var(--fs-small); }
    .g-sec { margin-top: var(--s-8); }
    .g-sec > h2 { padding-top: var(--s-3); border-top: var(--hair-ink); }
    .g-lead { color: var(--ash); max-width: 70ch; margin: calc(-1 * var(--s-2)) 0 var(--s-5); font-size: var(--fs-small); }
    .g-note { margin-top: var(--s-3); color: var(--ash); font-size: 0.875rem; max-width: 80ch; }
    .g-sub { margin: var(--s-6) 0 var(--s-3); color: var(--ash); }
    .g-empty { padding: var(--s-5); background: var(--ivory); border-left: 1px solid var(--ink); max-width: 70ch; }
    .g-empty__title { font-size: var(--fs-lead); line-height: 1.3; }
    .g-empty--compact { padding: var(--s-3) var(--s-4); color: var(--ash); font-size: var(--fs-small); }
    .g-empty p + p { margin-top: var(--s-2); color: var(--ash); font-size: var(--fs-small); }
    .g-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr)); gap: var(--s-4) var(--gutter); }
    .g-tile { padding-top: var(--s-3); border-top: var(--hair); }
    .g-tile__label { color: var(--ash); }
    .g-tile__value { font-size: clamp(2.25rem, 1.8rem + 1.5vw, 3rem); line-height: 1.1; margin-top: var(--s-2); font-variant-numeric: lining-nums tabular-nums; }
    .g-tile__delta { font-family: var(--sans); font-size: 0.8125rem; margin-top: var(--s-1); }
    .g-tile__delta span { color: var(--ash); }
    .g-funnel, .g-sources { display: grid; gap: var(--s-2); }
    .g-funnel__row, .g-sources li { display: grid; grid-template-columns: minmax(9rem, 1.2fr) minmax(8rem, 3fr) 5rem minmax(7rem, 1fr) minmax(12rem, 2fr); gap: var(--s-2) var(--s-4); align-items: center; padding: var(--s-2) 0; border-bottom: var(--hair); font-size: 0.875rem; }
    .g-funnel__label, .g-sources__name { font-family: var(--sans); font-weight: 500; }
    .g-funnel__track { height: 12px; background: var(--oat); display: block; }
    .g-funnel__bar { display: block; height: 100%; background: var(--ink); min-width: 1px; }
    .g-funnel__value { text-align: right; font-variant-numeric: tabular-nums; font-size: 1.125rem; }
    .g-funnel__rate, .g-funnel__step { color: var(--ash); }
    .g-funnel__step strong { color: var(--ink); font-weight: 500; }
    .g-funnel__row--worst { background: var(--ivory); box-shadow: -10px 0 0 var(--ivory), -12px 0 0 var(--error); }
    .g-funnel__row--worst .g-funnel__step strong { color: var(--error); }
    .g-funnel__flag { grid-column: 1 / -1; font-family: var(--sans); font-size: 0.75rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--error); }
    .g-actions { display: grid; grid-template-columns: repeat(auto-fill, minmax(20rem, 1fr)); gap: var(--s-5) var(--gutter); }
    .g-action { padding-top: var(--s-3); border-top: var(--hair-ink); }
    .g-action__kind { color: var(--ash); }
    .g-action__title { font-size: var(--fs-h3); line-height: 1.15; margin: var(--s-2) 0; font-weight: 400; }
    .g-action p { font-size: var(--fs-small); }
    .g-action__do { margin-top: var(--s-2); }
    .g-action__do .label { display: block; color: var(--ash); margin-bottom: 2px; }
    .g-opps { display: grid; grid-template-columns: repeat(auto-fit, minmax(17rem, 1fr)); gap: var(--s-5) var(--gutter); }
    .g-opp { padding-top: var(--s-3); border-top: var(--hair); font-size: 0.875rem; }
    .g-opp li { padding: var(--s-2) 0; border-bottom: var(--hair); }
    .g-sort { font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
    .g-sort:hover { color: var(--ink); }
    .dash th.num, .dash td.num { text-align: right; }
    .g-path { font-size: 0.75rem; }
    .g-checks { display: grid; gap: var(--s-2); max-width: 90ch; font-size: var(--fs-small); }
    .g-check { padding: var(--s-2) 0; border-bottom: var(--hair); }
    .g-check__mark { font-family: var(--sans); font-size: 0.75rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ash); margin-right: var(--s-2); }
    .g-check--ok .g-check__mark { color: var(--ink); }
    .g-events td:first-child { white-space: nowrap; }
    @media (max-width: 47.99rem) {
      .g-funnel__row, .g-sources li { grid-template-columns: 1fr 4.5rem; }
      .g-funnel__track { grid-column: 1 / -1; grid-row: 2; }
      .g-funnel__rate, .g-funnel__step { grid-column: 1 / -1; }
      .g-bar { position: static; }
    }
  </style>
</head>
<body>
  <main class="wrap dash">
    <p class="label muted">Unlisted · not indexed · not in the sitemap</p>
    <h1 class="h2">Growth &amp; SEO dashboard</h1>
    <p class="muted">What brings people to the invoice generator, what they do there, and what to work on next.</p>
    <nav class="g-jump" aria-label="Sections">
      <a class="link" href="#g-overview">Overview</a><a class="link" href="#g-funnel">Funnel</a><a class="link" href="#g-actions">What to do next</a>
      <a class="link" href="#g-opportunities">Opportunities</a><a class="link" href="#g-landing">Landing pages</a><a class="link" href="#g-templates">Templates</a>
      <a class="link" href="#g-content">Content</a><a class="link" href="#g-sources">Sources</a><a class="link" href="#g-search">Search</a>
      <a class="link" href="#g-setup">Setup &amp; events</a><a class="link" href="#audit">SEO audit</a>
    </nav>

    <div class="g-bar">
      <div class="g-range" role="group" aria-label="Date range">
        <button type="button" class="tpl-filter__btn" data-range="7" aria-pressed="false">Last 7 days</button>
        <button type="button" class="tpl-filter__btn" data-range="28" aria-pressed="true">Last 28 days</button>
        <button type="button" class="tpl-filter__btn" data-range="90" aria-pressed="false">Last 90 days</button>
        <button type="button" class="tpl-filter__btn" data-range="custom" aria-pressed="false">Custom</button>
        <span class="g-custom" data-g="custom" hidden>
          <label>From <input type="date" name="g-start"></label>
          <label>to <input type="date" name="g-end"></label>
          <button type="button" class="btn btn--sm btn--outline" data-action="apply-custom">Apply</button>
        </span>
      </div>
      <div class="g-conn">
        <span data-g="connect"></span>
        <label class="link-btn">Import Search Console CSV<input type="file" accept=".csv,text/csv" multiple data-g="import" class="visually-hidden"></label>
      </div>
    </div>
    <p class="g-period" data-g="period"></p>
    <p class="dash__bad" data-g="gsc-error" role="status"></p>
    <noscript><p class="g-empty">The growth sections need JavaScript. The SEO audit below works without it.</p></noscript>

    <section class="g-sec" id="g-overview"><h2 class="h3">Overview</h2><div data-g="overview"></div></section>
    <section class="g-sec" id="g-funnel"><h2 class="h3">Funnel</h2><p class="g-lead">Visitor → SEO page → generator → invoice → PDF. The step that loses the most people is marked.</p><div data-g="funnel"></div></section>
    <section class="g-sec" id="g-actions"><h2 class="h3">What should I do next?</h2><p class="g-lead">Observations from the measured data, each with the numbers behind it: the funnel’s biggest drop-off first, then problems on the site, then search and content. Pages are compared only with this site’s own pages.</p><div data-g="actions"></div></section>
    <section class="g-sec" id="g-opportunities"><h2 class="h3">Content opportunities</h2><div data-g="opportunities"></div></section>
    <section class="g-sec" id="g-landing"><h2 class="h3">Top landing pages</h2><div data-g="landing"></div></section>
    <section class="g-sec" id="g-templates"><h2 class="h3">Templates</h2><p class="g-lead">Template page views → “Customize this invoice” → generator opens → invoices → PDFs, with the rate at each step.</p><div data-g="templates"></div></section>
    <section class="g-sec" id="g-content"><h2 class="h3">SEO content performance</h2><div data-g="content"></div></section>
    <section class="g-sec" id="g-sources"><h2 class="h3">Traffic sources</h2><div data-g="sources"></div></section>
    <section class="g-sec" id="g-search"><h2 class="h3">Search Console</h2><div data-g="search"></div></section>
    <section class="g-sec" id="g-setup"><h2 class="h3">Setup &amp; events</h2><div data-g="setup"></div>
      <h3 class="label g-sub">Events recorded</h3>
      <div class="dash__scroll g-events"><table>
        <thead><tr><th>Event</th><th>When</th><th>Properties</th></tr></thead>
        <tbody>${EVENT_ROWS.map(([n, w, p]) => `<tr><td><code>${n}</code></td><td>${esc(w)}</td><td>${esc(p)}</td></tr>`).join('')}</tbody>
      </table></div>
      <p class="g-note">Every event also carries page_path, page_type, content_slug, device_type and the visit’s source, medium, campaign, landing page and referring site. Nothing typed into an invoice is ever included.</p>
    </section>

    <section class="g-sec dash__audit" id="audit">
    <h2 class="h3">SEO audit</h2>
    <p class="muted">Generated by the last build from the pages it wrote. Fix an issue in the content file named in the table, then rebuild.</p>
    <div class="dash__sum">
      <div><strong>${live.length}</strong><span class="label muted">Indexable pages</span></div>
      <div><strong>${content.templates.length}</strong><span class="label muted">Templates</span></div>
      <div><strong>${content.guides.length}</strong><span class="label muted">Guides</span></div>
      <div><strong>${content.tools.length}</strong><span class="label muted">Tools</span></div>
      <div><strong>${content.drafts.length}</strong><span class="label muted">Drafts</span></div>
      <div><strong>${avg}</strong><span class="label muted">Avg. words, content pages</span></div>
      <div><strong>${flagged.length}</strong><span class="label muted">Pages with issues</span></div>
    </div>

    <div class="dash__filters" role="group" aria-label="Filter by type">
      <button type="button" class="tpl-filter__btn" data-f="all" aria-pressed="true">All</button>
      ${types.map((t) => `<button type="button" class="tpl-filter__btn" data-f="${t}" aria-pressed="false">${esc(t)}</button>`).join('')}
    </div>
    <div class="dash__scroll">
      <table data-audit>
        <thead><tr><th>Type</th><th>URL</th><th>Title</th><th>Meta description</th><th>H1</th><th>Words</th><th>Links in / out</th><th>Schema</th><th>Indexable</th><th>Canonical</th><th>Issues</th></tr></thead>
        <tbody>${table}</tbody>
      </table>
    </div>
    </section>

    <section>
      <h2 class="h3">Drafts</h2>
      ${drafts}
    </section>

    <section>
      <h2 class="h3">Add a page</h2>
      <p>Pages come from the content database. Add a file, run <code>npm run build</code>, and the page, its card, breadcrumbs, structured data, related links and sitemap entry are generated. The build stops with a message if anything is missing, too long, too short or links to a page that does not exist.</p>
      ${Object.entries(SKELETONS).map(([k, s]) => `<h3 class="label mt-6">${esc(k)} · ${esc(s.file)}</h3><pre>${esc(s.body)}</pre>`).join('')}
    </section>
  </main>
  ${data('growth-config', config)}
  ${data('growth-index', index)}
  <script type="module" src="../assets/js/growth/dashboard.js?v=${appVersion}"></script>
  <script>
    document.querySelectorAll('[data-f]').forEach(function (b) {
      b.addEventListener('click', function () {
        document.querySelectorAll('[data-f]').forEach(function (x) { x.setAttribute('aria-pressed', String(x === b)); });
        document.querySelectorAll('[data-audit] tbody tr').forEach(function (r) { r.hidden = b.dataset.f !== 'all' && r.dataset.type !== b.dataset.f; });
      });
    });
  </script>
</body>
</html>
`;
}
